widget.solution:
import numpy as np


def topk_probs(logits, temperature, k):
    z = np.asarray(logits, dtype=float)
    if temperature == 0:
        p = np.zeros(len(z))
        p[np.argmax(z)] = 1.0
        return p
    z = z / temperature
    if k is not None:
        z = np.where(z < np.sort(z)[-k], -np.inf, z)
    e = np.exp(z - z.max())
    return e / e.sum()

